	it("preserves a local disclosure edit made before restore starts", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: { toolOutput: { title: "Current replayed result" } },
		});
		let resolveConnect!: () => void;
		const connect = new Promise<void>((resolve) => {
			resolveConnect = resolve;
		});
		bridge.connect.mockReturnValue(connect);
		bridge.hostContext = {
			toolInfo: { id: "late-card", tool: { name: "query_sdk" } },
		};
		bridge.callServerTool.mockImplementation(async ({ name }) => ({
			isError: false,
			...(name === "restore_lobu_app_result"
				? {
						structuredContent: {
							found: true,
							tool_name: "query_sdk",
							data: { title: "Historical snapshot" },
							view_state: { "details.open": false },
						},
					}
				: {}),
		}));

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, setViewState, viewState } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title}</span>
					<span data-testid="state">{String(viewState["details.open"])}</span>
					<button type="button" onClick={() => setViewState("details.open", true)}>
						Expand
					</button>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		expect(await screen.findByText("Current replayed result")).toBeInTheDocument();
		fireEvent.click(screen.getByRole("button", { name: "Expand" }));
		expect(screen.getByTestId("state")).toHaveTextContent("true");
		await act(async () => {
			resolveConnect();
			await connect;
		});
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "restore_lobu_app_result",
				arguments: { tool_call_id: "late-card", tool_name: "query_sdk" },
			}),
		);
		await waitFor(() => expect(screen.getByTestId("state")).toHaveTextContent("true"));
	});
});
